import json
import re
from docx import Document

def fill_template():
    data_path = 'employee_data.json'
    template_path = 'offer_letter_template.docx'
    output_path = '/root/offer_letter_filled.docx'

    try:
        with open(data_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error loading data: {e}")
        return

    try:
        doc = Document(template_path)
    except Exception as e:
        print(f"Error loading template: {e}")
        return

    relocation = data.get('RELOCATION_PACKAGE', 'No')

    def process_paragraph(para):
        text = para.text

        # Check for conditional markers
        # If Relocation is Yes, we just want to remove the markers (replace with empty string)
        # If Relocation is No, we would want to remove the content too, but instructions 
        # specifically focused on the "Yes" case (keep content). 
        # For completeness, if it was No, we'd need more complex logic. 
        # Given the prompt, we assume we just handle the cleanup.

        # We'll treat markers as just another thing to replace (with empty string)
        # But we check for them explicitly to handle "delete paragraph" if it was ONLY the marker.

        markers = ['{{IF_RELOCATION}}', '{{END_IF_RELOCATION}}']
        is_marker_line = False
        stripped = text.strip()
        if stripped in markers:
            is_marker_line = True

        # Perform replacements
        # We do this on the full text to handle split runs
        new_text = text

        # Data replacements
        pattern = r'\{\{([A-Z_]+)\}\}'
        matches = re.finditer(pattern, new_text)
        # We need to be careful replacing while iterating or matching.
        # Simpler: find all keys in text and replace.

        # Let's use the regex to find all placeholders
        found_placeholders = re.findall(pattern, new_text)
        for key in found_placeholders:
            placeholder = '{{' + key + '}}'
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))
            elif placeholder in markers:
                # Remove markers
                new_text = new_text.replace(placeholder, '')

        # If the line was just a marker, and now is empty (or whitespace),
        # we might want to ensure it is empty.
        if is_marker_line:
            new_text = '' 

        # If text changed, rebuild runs
        if new_text != text:
            # Clear all runs, put new text in first run
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                # If no runs but text existed? Rare in docx.
                para.add_run(new_text)

    # Process all paragraphs
    for para in doc.paragraphs:
        process_paragraph(para)

    # Process tables
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    process_paragraph(para)
                # Nested tables
                for nested in cell.tables:
                    for nrow in nested.rows:
                        for ncell in nrow.cells:
                            for npara in ncell.paragraphs:
                                process_paragraph(npara)

    # Process headers/footers
    for section in doc.sections:
        # Headers
        if section.header:
            for para in section.header.paragraphs:
                process_paragraph(para)
        # Footers
        if section.footer:
            for para in section.footer.paragraphs:
                process_paragraph(para)

    doc.save(output_path)
    print(f"Successfully created {output_path}")

if __name__ == '__main__':
    fill_template()

